import 'package:firebase_core/firebase_core.dart';
import 'package:flutter/material.dart';

import 'features/todo/pages/todo_list_page.dart';
import 'firebase_options.dart';

Future<void> main() async {
  // Flutter needs to be ready before any plugin (Firebase included) can run.
  WidgetsFlutterBinding.ensureInitialized();

  // Connects this app to the ibaCourse Firebase project — the config in
  // firebase_options.dart was generated by `flutterfire configure`.
  await Firebase.initializeApp(options: DefaultFirebaseOptions.currentPlatform);

  runApp(const MyApp());
}

class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Todo',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(colorScheme: ColorScheme.fromSeed(seedColor: Colors.deepPurple)),
      home: const TodoListPage(),
    );
  }
}
